import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent that answers customers' questions about their orders. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool: ' +
    'status, delivery ETA and tracking code. Quote the status, ETA and tracking code exactly as the tool returns them. ' +
    'If an order is not found, say so. Use what the customer told you earlier in the conversation, such as their order id.',
  tools: [lookupOrder],
});
